from rest_framework.negotiation import BaseContentNegotiation
from rest_framework.renderers import JSONRenderer, BrowsableAPIRenderer
from rest_framework.exceptions import NotAcceptable


class APIClientsOnlyNegotiation(BaseContentNegotiation):
    """
    همیشه JSON برمی‌گرداند مگر اینکه کاربر با مرورگر آمده باشد.
    برای APIهای عمومی که Browsable API نمی‌خواهند.
    """

    def select_parser(self, request, parsers):
        # پیش‌فرض DRF
        for parser in parsers:
            if parser.media_type in request.content_type:
                return parser
        return None

    def select_renderer(self, request, renderers, format_suffix=None):
        # اگر کاربر مرورگر است، BrowsableAPIRenderer
        user_agent = request.headers.get("User-Agent", "").lower()
        is_browser = any(
            browser in user_agent
            for browser in ["mozilla", "chrome", "safari", "edge", "firefox"]
        )

        if is_browser:
            for renderer in renderers:
                if isinstance(renderer, BrowsableAPIRenderer):
                    return (renderer, renderer.media_type)

        # در غیر این صورت JSON
        for renderer in renderers:
            if isinstance(renderer, JSONRenderer):
                return (renderer, renderer.media_type)

        raise NotAcceptable()

# در settings.py
